#include <bits/stdc++.h>
using namespace std;

int main() {
    long int n;
    cin.tie(nullptr);
    cin >> n;

    vector<string> v;

    do {
        int r = n % 10;
        string s = (r >= 5) ? "-O|" : "O-|";

        const string lower[] = {
            "-OOOO", "O-OOO", "OO-OO", "OOO-O", "OOOO-"
        };

        s += lower[r % 5];
        v.push_back(s);
        n /= 10;
    } while (n > 0);

    for (const string& s : v)
        cout << s << '\n';

    return 0;
}

